-- WP-05/WP-06 real dimension members (Member C).
-- Derived only from the real Tartan KBTP sample
-- samples/kbtp/01-01-22/1.csv
-- SHA-256 86342d09e5004102d765b82d04d16b43b6f15f2e7d829bfbde7909187d08a762.
-- Idempotent: safe to rerun. No deletes.
--
-- dim_vehicle: one row per distinct real ICAO 24-bit address (ID) in the sample,
-- with the first/last observed UTC timestamps from those rows. vehicle_type stays
-- NULL because the source does not define a vehicle type. source_system is
-- 'tartan' to match the WP-06 mapping brief; the fact loader normalizes casing.
-- dim_spatial_grid: no model grid is implemented, so facts use grid_key = -1.
-- dim_weather: no invented rows; stays -1 until real METAR rows are loaded.
-- dim_time and dim_site real members are seeded by 02_seed.sql.

ON CONFLICT (source_system, source_entity_id) DO UPDATE
SET first_seen_ts = LEAST(
        v.first_seen_ts,
        EXCLUDED.first_seen_ts
    ),
    last_seen_ts = GREATEST(
        v.last_seen_ts,
        EXCLUDED.last_seen_ts
    );

-- Advance the identity sequence past the seeded rows so later inserts never collide.
SELECT setval(
    pg_get_serial_sequence('project_dw.dim_vehicle', 'vehicle_key'),
    GREATEST(1, (SELECT COALESCE(MAX(vehicle_key), 0) FROM project_dw.dim_vehicle)),
    true
);
